sql:
SELECT ControllerName
FROM lc_actualcontroller
WHERE ChiName = '五粮液' OR ChiName = '张裕';

SELECT ReceiverName, SumAfterRece, PCTAfterTran
FROM lc_sharetransfer
WHERE SecuCode = 'Shengtian Network' AND TranDate BETWEEN '2017-01-01' AND '2017-12-31';

SELECT BondAbbr, BondCode, HoldVolume, SecuAbbr
FROM mf_bondportifoliodetail
WHERE SecuAbbr LIKE '%Boshi Theme%' AND HoldVolume > 100000;

SELECT "lc_stockarchives.LegalRepr" AS LegalRepresentative, "lc_stockarchives.GeneralManager" AS GeneralManager
FROM "lc_stockarchives"
WHERE "lc_stockarchives.ChiName" = 'Hang Seng Electronics';

SELECT TradingDay, TurnoverVolume, TurnoverValue
FROM qt_dailyquote
WHERE ChiName = '凯撒文化';

SELECT BasisCode, RatioFloor, RatioCeiling 
FROM ed_taxrate 
WHERE ItemName = 'Transaction Commission Rate' AND SecuMarket = 'A-share';

SELECT DISTINCT ChiNameAbbr AS "组织形式" 
FROM mf_fundmanagernew 
WHERE ChiName = '华夏基金管理有限公司';

SELECT IssueVolFloor, IssueVolCeiling
FROM lc_ashareseasonednewissue
WHERE SecuCode = '002305';

SELECT Name 
FROM mf_fundmanagernew 
WHERE SecuCode LIKE '15%' AND Performance > 0.7;

SELECT DISTINCT mf_investadvisoroutline.InvestAdvisorName 
FROM mf_investadvisoroutline 
WHERE mf_investadvisoroutline.GeneralManager LIKE '%Liu%';

SELECT InvolvedSum, PCTOfTotalShares 
FROM lc_sharefp 
WHERE SecuCode = '300100';
